    @staticmethod
    def math_rule_0001(x: float, y: float) -> dict:
        """Rule #1: Theorem on polynomial expansion and calculus derivative for degree 1."""
        coeff = 1 * 1.5
        derivative_val = coeff * (x ** (1 - 1))
        integral_val = (coeff / (1 + 1)) * (x ** (1 + 1))
        return {
            "rule_id": 1,
            "name": "Polynomial Differentiation & Integration Rule #1",
            "formula": r"\frac{d}{dx}[1 x^{1}] = 1 x^{0}",
            "derivative": derivative_val,
            "integral": integral_val,
            "explanation": "Applies power rule for derivative and power rule for integration."
        }

